import{z as A,x as s,o,c as p,q as r,j as t,D as e,d as i,s as l,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"点定位","description":"","frontmatter":{"title":"点定位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/point-location.md","filePath":"cs/point-location.md","lastUpdated":1791063341000}'),d={name:"cs/point-location.md"};function D(u,a,c,m,h,k){const n=s("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="点定位" tabindex="-1">点定位 <a class="header-anchor" href="#点定位" aria-label="Permalink to &quot;点定位&quot;">​</a></h1><div class="epigraph"><p>平面剖分成面后，询问点落在哪一面：梯形图或 Kirkpatrick 层次，$O(n)$ 空间 $O(\\log n)$ 查询。</p><footer>—— 据 Kirkpatrick, Optimal Search in Planar Subdivisions, 1983；Mulmuley、Seidel 随机增量梯形图整理</footer></div><p>上一课<a href="/cs/voronoi-delaunay">Voronoi 与 Delaunay</a>给出剖分。缺口是查询：点 \\(q\\) 在哪个面/哪条 Delaunay 边的哪侧。朴素 \\(O(n)\\) 走。本课点定位结构。不重写 Fortune。后课几何精度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>梯形图：过每个顶点作竖线直到撞边，面变梯形。随机增量期望 \\(O(n)\\) 大小、\\(O(\\log n)\\) 历史 DAG 查询。Kirkpatrick：独立集收缩层次，\\(\\log\\) 层。步行（沿 Delaunay 走）实践快但最坏差。</p><p>缺口是数据结构，不是再三角化。</p><h3 id="不是最近邻本身" tabindex="-1">不是最近邻本身 <a class="header-anchor" href="#不是最近邻本身" aria-label="Permalink to &quot;不是最近邻本身&quot;">​</a></h3><p>最近站点可用 Voronoi 定位，或 k-d 树。本课一般剖分。k-d 树是正交，点名。</p><p><span class="marginnote">Kirkpatrick 1983。CGAL 实现随机梯形图。后课鲁棒性：定位依赖谓词符号。</span></p><p><span class="marginnote">直觉类比：梯形图像在剖分的每个路口都拉起两根垂直的「灯柱」，灯柱一碰到边就停。奇形怪状的面全被切成上下底水平的梯形，而「这个点在梯形里吗」只需要一两次坐标比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理剖分。询问沿 DAG 或层次下降。动态插入更重（随机增量在线）。</p>',12)),(o(),t(B,null,{default:e(()=>[l(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E5%B9%B3%E9%9D%A2%E5%89%96%E5%88%86%22%5D%20--%3E%20TRAP%5B%22%E6%A2%AF%E5%BD%A2%E5%9B%BE%20%2F%20%E5%B1%82%E6%AC%A1%22%5D%0A%20%20TRAP%20--%3E%20Q%5B%22O(log%20n)%20%E7%82%B9%E5%AE%9A%E4%BD%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与扫描线：梯形图常随机增量不是从左扫一次完。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"每层面数减常因子，查询下降对数。历史 DAG 记录「被谁切开」。与二叉搜索树：几何键是区域包含。与半平面：对偶可把某些定位变成凸包切。",-1)),a[6]||(a[6]=E("p",null,"竖线切割到底把查询变成什么样的一路下降？",-1)),(o(),t(B,null,{default:e(()=>[l(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%BB%BB%E6%84%8F%E5%B9%B3%E9%9D%A2%E5%89%96%E5%88%86%22%5D%20--%3E%20V%5B%22%E8%BF%87%E6%AF%8F%E4%B8%AA%E9%A1%B6%E7%82%B9%E4%BD%9C%E7%AB%96%E7%9B%B4%E7%BA%BF%22%5D%0A%20%20V%20--%3E%20STOP%5B%22%E7%AB%96%E7%BA%BF%E4%B8%8A%E4%B8%8B%E5%BB%B6%E4%BC%B8%EF%BC%8C%E6%92%9E%E5%88%B0%E7%AC%AC%E4%B8%80%E6%9D%A1%E8%BE%B9%E5%B0%B1%E5%81%9C%22%5D%0A%20%20STOP%20--%3E%20TRAP%5B%22%E6%89%80%E6%9C%89%E9%9D%A2%E8%A2%AB%E5%88%87%E6%88%90%E6%A2%AF%E5%BD%A2%22%5D%0A%20%20TRAP%20--%3E%20DAG%5B%22%E6%AF%8F%E4%B8%AA%E6%A2%AF%E5%BD%A2%E5%AF%B9%E5%BA%94%20DAG%20%E4%B8%80%E4%B8%AA%E8%8A%82%E7%82%B9%22%5D%0A%20%20DAG%20--%3E%20SEARCH%5B%22%E6%9F%A5%E8%AF%A2%EF%BC%9A%E6%AF%94%E8%BE%83%E5%B7%A6%E4%B8%8E%E5%8F%B3%E3%80%81%E4%B8%8A%E4%B8%8E%E4%B8%8B%EF%BC%8C%E9%80%90%E5%B1%82%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SEARCH%20--%3E%20LOG%5B%22%E6%AF%94%E8%BE%83%E6%AC%A1%E6%95%B0%E4%B8%8E%E5%B1%82%E6%95%B0%E5%90%8C%E9%98%B6%EF%BC%8C%E5%AF%B9%E6%95%B0%E7%BA%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：100 万个顶点的地图，朴素逐面检查要约一百万次判断；\\(O(\\log n)\\) 定位只需 20 次上下比较（\\(2^{20}\\approx 10^6\\)）——从「翻遍全书」变成「对半猜页码」。</span></p><p><span class="marginnote">常见误区：以为点定位的难点是查询慢。真正的坑是浮点：竖线算不算撞上这条边、询问点恰好在边上，符号判断在舍入误差下会翻转，DAG 走错一层结果就错——这正是后课几何鲁棒性要接的盘。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维点定位。动态删点不写。后课默认：静态剖分 \\(O(\\log n)\\) 定位。下一课几何精度与鲁棒性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剖分查询用梯形图或 Kirkpatrick。</li><li>\\(O(n)\\) 空间、\\(O(\\log n)\\) 查询。</li><li>步行实用、最坏弱。</li><li>出处：Kirkpatrick, 1983；随机增量梯形图。</li></ul>',6))])}const F=A(d,[["render",D]]);export{f as __pageData,F as default};
